#!/bin/bash
set -euo pipefail

# Test: bin/join-gh.sh — gh CLI joiner for Egregore (companion to init-gh.sh)
# Generated by /qa on 2026-04-16 for dev/oguzhan/validate-pat-flow-oss-release
# Covers: source guards, arg parsing, portability, npx-parity behaviors.

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
JOIN="$SCRIPT_DIR/bin/join-gh.sh"

PASS=0
FAIL=0
pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; return 0; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; return 0; }

echo "Testing: bin/join-gh.sh"
echo

# ── File existence + shebang + exec bits ──────────────────────────

[ -f "$JOIN" ] && pass "join-gh.sh exists" || fail "join-gh.sh missing"
head -1 "$JOIN" | grep -q '^#!/bin/bash' \
  && pass "shebang is #!/bin/bash" \
  || fail "wrong or missing shebang"

# ── bash 3.2 syntax check ─────────────────────────────────────────

/bin/bash -n "$JOIN" 2>/dev/null \
  && pass "bash 3.2 syntax clean" \
  || fail "bash -n rejects the script"

# ── Source-level portability guards ───────────────────────────────

! grep -qE '^[[:space:]]*mapfile[[:space:]]' "$JOIN" \
  && pass "no mapfile (bash 4+ only)" \
  || fail "uses mapfile — breaks on bash 3.2"

! grep -q 'readlink -f' "$JOIN" \
  && pass "no readlink -f (GNU-only)" \
  || fail "uses readlink -f"

! grep -qE 'sed -i[^ ]* ' "$JOIN" \
  && pass "no sed -i" \
  || fail "uses sed -i"

! grep -q 'date -d ' "$JOIN" \
  && pass "no date -d (GNU-only)" \
  || fail "uses date -d"

! grep -q 'declare -A' "$JOIN" \
  && pass "no associative arrays" \
  || fail "uses declare -A"

grep -q '^set -euo pipefail$' "$JOIN" \
  && pass "set -euo pipefail at top" \
  || fail "missing set -euo pipefail"

! grep -q 'source .env' "$JOIN" \
  && pass "never sources .env" \
  || fail "sources .env"

! grep -q '…' "$JOIN" \
  && pass "no Unicode ellipsis" \
  || fail "Unicode ellipsis present"

# ── Arg parsing ───────────────────────────────────────────────────

grep -q 'ORG_REPO="\${1:-}"' "$JOIN" \
  && pass "accepts <owner>/<repo> as positional arg" \
  || fail "no positional arg parsing"

grep -qE '\$\{ORG_REPO%%/\*\}' "$JOIN" \
  && pass "splits owner from repo" \
  || fail "doesn't split owner/repo"

grep -q 'Expected <owner>/<repo>' "$JOIN" \
  && pass "clear error on bad arg format" \
  || fail "no validation for owner/repo format"

# ── Pre-flight ────────────────────────────────────────────────────

grep -q 'Missing required tool' "$JOIN" \
  && pass "preflight: has missing-tool error path" \
  || fail "preflight: no missing-tool error"

grep -qE 'for tool in.* gh ' "$JOIN" \
  && pass "preflight: checks for gh" \
  || fail "preflight: does not check for gh"

grep -qE 'gh auth status' "$JOIN" \
  && pass "preflight: runs gh auth status" \
  || fail "no gh auth status check"

# ── Invitation acceptance ─────────────────────────────────────────

grep -q '/user/repository_invitations' "$JOIN" \
  && pass "lists pending repository invitations" \
  || fail "no invitation listing"

grep -qE 'gh api.*--method PATCH.*/user/repository_invitations/' "$JOIN" \
  && pass "accepts invitations via PATCH" \
  || fail "doesn't accept invitations"

grep -q 'repository.owner.login ==' "$JOIN" \
  && pass "filters invitations by owner" \
  || fail "doesn't filter invitations by owner"

# ── Core repo clone + config read ─────────────────────────────────

grep -qE 'gh repo clone.*\$OWNER/\$REPO' "$JOIN" \
  && pass "clones core repo via gh" \
  || fail "no gh repo clone for core"

grep -q 'egregore.json' "$JOIN" \
  && pass "reads egregore.json from clone" \
  || fail "doesn't read egregore.json"

grep -q 'Ask the admin to finish setup first' "$JOIN" \
  && pass "clear error when egregore.json missing" \
  || fail "no guidance when config is absent"

# ── Memory repo discovery + clone ─────────────────────────────────

grep -qE 'memory_repo' "$JOIN" \
  && pass "reads memory_repo URL from config" \
  || fail "doesn't read memory_repo from config"

grep -qE 'gh repo clone.*MEMORY_(REPO_NAME|FULL)' "$JOIN" \
  && pass "clones memory repo as sibling" \
  || fail "no memory repo clone"

# ── Credential helper fix (shared with init-gh.sh) ────────────────

grep -q 'configure_gh_creds' "$JOIN" \
  && pass "configure_gh_creds function defined" \
  || fail "missing configure_gh_creds — multi-account gh users will see push failures"

grep -q "credential.helper '!gh auth git-credential'" "$JOIN" \
  && pass "repo-local credential.helper uses gh" \
  || fail "no !gh auth git-credential helper"

# ── .env + state ──────────────────────────────────────────────────

grep -q 'GITHUB_TOKEN=\$GH_TOKEN' "$JOIN" \
  && pass "writes GITHUB_TOKEN to .env from gh auth token" \
  || fail "doesn't write GITHUB_TOKEN to .env"

grep -qE 'chmod 600 "\$ENV_FILE"' "$JOIN" \
  && pass ".env chmod 600 applied after write" \
  || fail ".env not protected with 0600"

grep -q 'usage_type: "joiner_group"' "$JOIN" \
  && pass ".egregore-state.json marks as joiner_group" \
  || fail "state file doesn't mark joiner_group"

grep -q -- '--argjson onboarding_complete' "$JOIN" \
  && pass "onboarding_complete encoded as JSON bool (preserves true on re-run)" \
  || fail "onboarding_complete may be a string or always false"

# ── Managed repos ─────────────────────────────────────────────────

grep -qE 'jq .* .repos ' "$JOIN" || grep -qE 'jq .\.repos' "$JOIN" \
  && pass "iterates config.repos" \
  || fail "doesn't iterate config.repos"

grep -q 'not invited yet, or different owner' "$JOIN" \
  && pass "graceful warn when managed-repo clone fails" \
  || fail "no graceful fallback for missing managed-repo access"

# ── Shell alias (npx parity) ──────────────────────────────────────

grep -q 'install_shell_alias' "$JOIN" \
  && pass "install_shell_alias function defined" \
  || fail "no install_shell_alias — npx parity gap"

grep -q 'claude start' "$JOIN" \
  && pass "alias command uses 'claude start'" \
  || fail "alias command doesn't use 'claude start'"

grep -qE '\.zshrc|\.bashrc|config.fish' "$JOIN" \
  && pass "handles multiple shell profiles" \
  || fail "no shell profile detection"

# ── Welcome note ──────────────────────────────────────────────────

grep -q 'WELCOME_FILE' "$JOIN" \
  && pass "reads welcome note from memory/people/<login>.md" \
  || fail "no welcome-note reading"

grep -q 'invited_by:' "$JOIN" \
  && pass "extracts inviter from frontmatter" \
  || fail "doesn't extract invited_by"

# ── Telegram link ─────────────────────────────────────────────────

grep -q 'telegram_group_link' "$JOIN" \
  && pass "shows Telegram group link if configured" \
  || fail "doesn't surface telegram_group_link"

# ── Idempotency ───────────────────────────────────────────────────

grep -qE 'already exists .* leaving as-is' "$JOIN" \
  && pass "re-run handles pre-existing clones" \
  || fail "no re-run protection on clones"

# ── QA finding: memory repo clone uses full URL (cross-owner safe) ──

# The founder's egregore.json stores memory_repo as a full HTTPS URL. The joiner
# should honor the URL's OWNER, not reconstruct from the core repo's owner.
# npx's localJoinFlow uses memoryUrl directly (local.js:773). If the config
# points memory to a different owner (rare today, but possible in connected-mode
# setups), our joiner should still work.
if grep -qE 'gh repo clone .MEMORY_URL' "$JOIN" \
   || grep -qE 'gh repo clone .MEMORY_(OWNER|FULL)' "$JOIN" \
   || grep -qE 'MEMORY_OWNER' "$JOIN"; then
  pass "memory clone uses URL or derived owner (cross-owner safe)"
else
  fail "memory clone hardcodes \$OWNER/\$MEMORY_REPO_NAME — ignores cross-owner memory URLs"
fi

# ── QA finding: symlink must be gated on MEMORY_DIR existence ─────

# If memory clone fails but the script continues (warn-and-continue), the next
# step unconditionally creates ln -s $MEMORY_DIR → memory/, resulting in a
# dangling symlink. First `cd memory` would fail.
# Look within the "Linking memory" block for a MEMORY_DIR existence guard.
SYMLINK_BLOCK="$(awk '/Linking memory/,/^fi$/' "$JOIN")"
if echo "$SYMLINK_BLOCK" | grep -qE '\[ ! -d "\$MEMORY_DIR/\.git"|-d "\$MEMORY_DIR"'; then
  pass "symlink creation is gated on MEMORY_DIR existence"
else
  fail "symlink created unconditionally — leaves dangling link if memory clone failed"
fi

# ── QA finding: connected-mode joiner warning ─────────────────────

# Connected-mode Egregores need EGREGORE_API_KEY in .env; the joiner only
# writes GITHUB_TOKEN. Joining a connected-mode Egregore without the API key
# causes obscure failures later in skills.
if grep -qE 'mode.*connected|mode == "connected"|\.mode' "$JOIN"; then
  pass "joiner checks mode (can warn when joining connected-mode Egregore)"
else
  fail "joiner ignores egregore.json mode — user may miss API key requirement"
fi

# ── Summary ───────────────────────────────────────────────────────

echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
